package org.mockito;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.Collection;
import java.util.List;
import java.util.Map;
import java.util.Set;
import org.hamcrest.Matcher;
import org.junit.*;
import org.junit.Test;
import org.mockito.internal.matchers.*;
import org.mockito.internal.matchers.apachecommons.ReflectionEquals;
import org.mockito.internal.progress.HandyReturnValues;
import org.mockito.internal.progress.MockingProgress;
import org.mockito.internal.progress.ThreadSafeMockingProgress;
import static org.junit.Assert.*;
import static org.junit.Assert.assertNull;
import static org.mockito.Matchers.same;

public class Matchers_same_TriageGen2Test {

    @Test
    public void testSame_WithInteger() {
        Integer value = 10;
        Integer result = same(value);
        // Since reportMatcher(...).returnNull() is called, 
        // the method is designed to return null in the context of Mockito's argument matching logic.
        assertNull(result);
    }

    @Test
    public void testSame_WithString() {
        String value = "test";
        String result = same(value);
        assertNull(result);
    }

    @Test
    public void testSame_WithObject() {
        Object value = new Object();
        Object result = same(value);
        assertNull(result);
    }

    @Test
    public void testSame_WithNull() {
        Object value = null;
        Object result = same(value);
        assertNull(result);
    }

    @Test
    public void testSame_WithDouble() {
        Double value = 10.5;
        Double result = same(value);
        assertNull(result);
    }
}
